import { beforeAll, expect, it } from "vite-plus/test";
import { writeFileSync } from "node:fs";
import { createConcreteRuntime } from "../src/concrete/runtime.js";
import { getSymbolicEngine } from "../src/symbolic/load-engine.js";
import { buildScriptFixture } from "./helpers/build-script-fixture.js";
import { createNativeRuntime } from "./helpers/native-runtime.js";

let source: string;
beforeAll(async () => {
  const chunk = await buildScriptFixture(
    new URL("./fixtures/symbolic-react-tree.tsx", import.meta.url),
    "production",
  );
  source = chunk.code;
});

it.each([false, true].flatMap((enabled) => [false, true].map((details) => ({ enabled, details }))))(
  "specializes a real React tree with correlated Boolean decisions, enabled=$enabled details=$details",
  async ({ enabled, details }) => {
    const runtime = await createConcreteRuntime();
    const native = createNativeRuntime();
    const { api } = await getSymbolicEngine();
    try {
      runtime.evaluate(source);
      native.evaluate(source);
      expect(runtime.readString("JSON.stringify(fixture.versions)")).toBe('["19.3.0","19.3.0"]');
      runtime.evaluate("fixture.mount()");
      native.evaluate("fixture.mount()");
      runtime.drainJobs();
      native.drainJobs();
      expect(runtime.readString("fixture.observe()")).toBe(native.evaluate("fixture.observe()"));
      const previous = api.surroundingAgent;
      api.setSurroundingAgent(runtime.agent);
      let enabledDecisions = 0;
      let detailsDecisions = 0;
      try {
        const enabledInput = api.BooleanValue.createAbstract();
        const detailsInput = api.BooleanValue.createAbstract();
        api.X(api.CreateDataPropertyOrThrow(runtime.realm.GlobalObject, "enabled", enabledInput));
        api.X(api.CreateDataPropertyOrThrow(runtime.realm.GlobalObject, "details", detailsInput));
        const compiled = api.EnsureCompletion(
          runtime.realm.compileScript(`
          fixture.update(enabled, details);
          fixture.observe();
        `),
        );
        if (compiled.Type !== "normal") throw Error("Expected compiled update");
        runtime.agent.evaluate(api.ScriptEvaluation(compiled.Value), () => {}, false);
        let step = runtime.agent.resumeEvaluate({
          pauseOnAbstractBoolean: true,
          noBreakpoint: true,
        });
        while (!step.done) {
          const decision = step.value;
          if (!decision) throw Error("Unexpected debugger pause");
          if (enabledDecisions + detailsDecisions >= 16)
            throw Error("Unexpected decision expansion");
          let choice: boolean;
          if (decision.value === enabledInput) {
            enabledDecisions++;
            choice = enabled;
          } else if (decision.value === detailsInput) {
            detailsDecisions++;
            choice = details;
          } else {
            throw Error("Decision lost input identity");
          }
          if (enabledDecisions + detailsDecisions === 1) {
            const seen = new Set<object>();
            const counts = new Map<string, number>();
            const sentinel = new Error("Unowned React tree state");
            const unsupported = new Map<string, number>();
            let selectedObjects = 0;
            expect(() => runtime.agent.captureEvaluation({
              references: value => {
                if (seen.size >= 50000) throw Error("Audit reference budget exceeded");
                seen.add(value);
                const name = Object.getPrototypeOf(value)?.constructor?.name ?? "null-prototype";
                counts.set(name, (counts.get(name) ?? 0) + 1);
                const references: unknown[] = [];
                if (value instanceof api.ObjectValue) {
                  const entries = api.isMapObject(value) ? value.MapData : api.isWeakMapObject(value) ? value.WeakMapData : undefined;
                  for (const entry of entries ?? []) references.push(entry.Key, entry.Value);
                }
                if (value instanceof api.CallSite) references.push(value.context);
                if (Array.isArray(value)) references.push(...value);
                else if (typeof Reflect.get(value, "mark") === "function") {
                  Reflect.apply(Reflect.get(value, "mark"), value, [(reference: unknown) => references.push(reference)]);
                }
                return references;
              },
              capture: roots => {
                for (const value of seen) {
                  if (!(value instanceof api.ObjectValue)) continue;
                  try {
                    const checkpoint = api.createStateCheckpoint({ objects: [value] });
                    checkpoint.release();
                    selectedObjects++;
                  } catch (error) {
                    const keys: string[] = [];
                    value.properties.forEach((_descriptor, key) => { if (typeof key === "string") keys.push(key); else if (key instanceof api.JSStringValue) keys.push(key.stringValue()); });
                    const key = JSON.stringify({ slots: value.internalSlotsList, parameterMap: api.isArgumentExoticObject(value) ? value.ParameterMap === undefined ? "unmapped" : "mapped" : null, privateElements: value.PrivateElements.length, constructedBy: value.ConstructedBy.length, keys: keys.slice(0, 12), hasPrototype: "Prototype" in value, hasExtensible: "Extensible" in value, methods: ["GetPrototypeOf", "SetPrototypeOf", "IsExtensible", "PreventExtensions", "GetOwnProperty", "DefineOwnProperty", "HasProperty", "Get", "Set", "Delete", "OwnPropertyKeys"].filter(name => Reflect.get(value, name) !== Reflect.get(api.ObjectValue.prototype, name)), error: error instanceof Error ? error.message : "unknown" });
                    unsupported.set(key, (unsupported.get(key) ?? 0) + 1);
                  }
                }
                let combined: unknown;
                try {
                  const checkpoint = api.createStateCheckpoint({
                    objects: [...seen].filter(value => value instanceof api.ObjectValue),
                    environments: [...seen].filter(value => value instanceof api.DeclarativeEnvironmentRecord || value instanceof api.GlobalEnvironmentRecord),
                    contexts: [...seen].filter(value => value instanceof api.ExecutionContext),
                    callSites: [...seen].filter(value => value instanceof api.CallSite),
                  });
                  combined = { objectCount: checkpoint.objectCount, environmentCount: checkpoint.environmentCount, bindingCount: checkpoint.bindingCount, contextCount: checkpoint.contextCount, callSiteCount: checkpoint.callSiteCount };
                  checkpoint.release();
                } catch (error) {
                  combined = { error: error instanceof Error ? error.message : String(error) };
                }
                writeFileSync(`/tmp/bippy-react-tree-context-frontier-${enabled}-${details}.json`, JSON.stringify({ directRoots: roots.values.length, controlObjects: roots.controlOwnedObjects.length, seen: seen.size, counts: [...counts], selectedObjects, unsupported: [...unsupported], combined }, null, 2));
                throw sentinel;
              },
            })).toThrow(sentinel);
          }
          runtime.agent.AgentRecord.KeptAlive.clear();
          api.gc();
          step = runtime.agent.resumeEvaluate({
            abstractBooleanDecision: { resume: "abstract-boolean", decision, value: choice },
            noBreakpoint: true,
          });
        }
        const completion = api.EnsureCompletion(step.value);
        expect(completion.Type).toBe("normal");
        if (!(completion.Value instanceof api.JSStringValue))
          throw Error("Expected committed tree observation");
        native.evaluate(`fixture.update(${enabled}, ${details})`);
        expect(completion.Value.stringValue()).toBe(native.evaluate("fixture.observe()"));
      } finally {
        api.setSurroundingAgent(previous);
      }
      expect(enabledDecisions).toBe(details ? 4 : 3);
      expect(detailsDecisions).toBe(1);
      runtime.drainJobs();
      native.drainJobs();
      expect(runtime.readString("fixture.observe()")).toBe(native.evaluate("fixture.observe()"));
      runtime.evaluate("fixture.unmount()");
      native.evaluate("fixture.unmount()");
      runtime.drainJobs();
      native.drainJobs();
      expect(runtime.readString("fixture.observe()")).toBe(native.evaluate("fixture.observe()"));
      expect(runtime.unhandledRejections.size).toBe(0);
      expect(runtime.uncaughtExceptions).toEqual([]);
    } finally {
      runtime.dispose();
    }
  },
);

